            equals: userId,
          },
          teamId: {
            equals: user?.teamId,
          },
        },
        data: {
          role: body.role,
        },
      });

      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
```
This looks correct for MSW v2 (`http.patch`, `HttpResponse.json`). `params` holds the URL parameters. `request.json()` gets the body. `db.user.update` is how `@mswjs/data` updates records. `persistDb` saves to the mock DB file/localStorage.

One thing: `params.userId` is a string because URL params in MSW are passed as strings. I cast it to `string`, which is fine.

